function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const O = '#0d0a08', P1 = '#2a2620', P2 = '#4a443c', P3 = '#6a6358', Moss = '#3d5a3d';
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };
  px(0, 0, 32, 32, P1);
  for (let y = 0; y < 32; y += 4) {
    for (let x = 0; x < 32; x += 4) {
      if (((x / 4) + (y / 4)) % 2 === 0) px(x, y, 4, 4, P2);
    }
  }
  px(1, 1, 2, 1, P3);
  px(17, 9, 1, 1, P3);
  px(7, 21, 2, 1, Moss);
  px(24, 5, 1, 2, Moss);
  px(13, 27, 1, 1, Moss);
}
